BEGIN;
CREATE TABLE IF NOT EXISTS synth_users(id BIGSERIAL PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,name TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS synth_tenants(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS synth_memberships(tenant_id BIGINT NOT NULL REFERENCES synth_tenants(id),user_id BIGINT NOT NULL REFERENCES synth_users(id),role TEXT NOT NULL CHECK(role IN('spec_author','data_steward','privacy_reviewer','generator_operator','release_manager','auditor','admin')),active BOOLEAN NOT NULL DEFAULT TRUE,PRIMARY KEY(tenant_id,user_id));
CREATE TABLE IF NOT EXISTS synth_specs(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES synth_tenants(id),spec_ref TEXT NOT NULL,version_ref TEXT NOT NULL,spec JSONB NOT NULL,spec_digest CHAR(64) NOT NULL,created_by BIGINT NOT NULL REFERENCES synth_users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,spec_ref,version_ref),UNIQUE(tenant_id,spec_digest));
CREATE TABLE IF NOT EXISTS synth_jobs(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES synth_tenants(id),spec_id BIGINT NOT NULL REFERENCES synth_specs(id),state TEXT NOT NULL DEFAULT 'draft' CHECK(state IN('draft','validated','privacy_review','rejected','approved','generation_queued','generating','generation_failed','evaluating','evaluation_failed','release_review','released')),revision INTEGER NOT NULL DEFAULT 1,idempotency_key TEXT NOT NULL,created_by BIGINT NOT NULL REFERENCES synth_users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS synth_privacy_reviews(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES synth_tenants(id),job_id BIGINT NOT NULL REFERENCES synth_jobs(id),review JSONB NOT NULL,review_digest CHAR(64) NOT NULL,reviewed_by BIGINT NOT NULL REFERENCES synth_users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,job_id,review_digest));
CREATE TABLE IF NOT EXISTS synth_generation_outbox(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES synth_tenants(id),job_id BIGINT NOT NULL REFERENCES synth_jobs(id),idempotency_key TEXT NOT NULL,payload JSONB NOT NULL,payload_digest CHAR(64) NOT NULL,status TEXT NOT NULL DEFAULT 'queued' CHECK(status IN('queued','processing','retry','succeeded','dead_letter')),attempts INTEGER NOT NULL DEFAULT 0,next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),provider_job_ref TEXT,manifest_uri TEXT,manifest_digest CHAR(64),last_error_code TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS synth_batches(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES synth_tenants(id),job_id BIGINT NOT NULL REFERENCES synth_jobs(id),provider_job_ref TEXT NOT NULL,manifest_uri TEXT NOT NULL,manifest JSONB NOT NULL,manifest_digest CHAR(64) NOT NULL,batch_digest CHAR(64) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,job_id,batch_digest));
CREATE TABLE IF NOT EXISTS synth_evaluations(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES synth_tenants(id),job_id BIGINT NOT NULL REFERENCES synth_jobs(id),batch_id BIGINT NOT NULL REFERENCES synth_batches(id),evaluation JSONB NOT NULL,evaluation_digest CHAR(64) NOT NULL,passed BOOLEAN NOT NULL,evaluated_by BIGINT NOT NULL REFERENCES synth_users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,batch_id,evaluation_digest));
CREATE TABLE IF NOT EXISTS synth_release_approvals(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES synth_tenants(id),job_id BIGINT NOT NULL REFERENCES synth_jobs(id),evaluation_id BIGINT NOT NULL REFERENCES synth_evaluations(id),privacy_review_id BIGINT NOT NULL REFERENCES synth_privacy_reviews(id),approval JSONB NOT NULL,approval_digest CHAR(64) NOT NULL,approved_by BIGINT NOT NULL REFERENCES synth_users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,job_id,approval_digest));
CREATE TABLE IF NOT EXISTS synth_releases(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES synth_tenants(id),job_id BIGINT NOT NULL REFERENCES synth_jobs(id),approval_id BIGINT NOT NULL REFERENCES synth_release_approvals(id),object_uri TEXT NOT NULL,object_digest CHAR(64) NOT NULL,kms_key_ref TEXT NOT NULL,retention_until TIMESTAMPTZ NOT NULL,release_receipt_digest CHAR(64) NOT NULL,released_by BIGINT NOT NULL REFERENCES synth_users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,job_id,release_receipt_digest));
CREATE TABLE IF NOT EXISTS synth_integrations(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES synth_tenants(id),integration_ref TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('email','webhook','queue')),destination_ref TEXT NOT NULL,secret_ref TEXT,active BOOLEAN NOT NULL DEFAULT TRUE,created_by BIGINT NOT NULL REFERENCES synth_users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,integration_ref));
CREATE TABLE IF NOT EXISTS synth_notification_outbox(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES synth_tenants(id),integration_id BIGINT NOT NULL REFERENCES synth_integrations(id),event_type TEXT NOT NULL,idempotency_key TEXT NOT NULL,message JSONB NOT NULL,message_digest CHAR(64) NOT NULL,status TEXT NOT NULL DEFAULT 'queued' CHECK(status IN('queued','processing','retry','succeeded','dead_letter')),attempts INTEGER NOT NULL DEFAULT 0,next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),delivery_ref TEXT,evidence_digest CHAR(64),last_error_code TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS synth_webhook_receipts(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES synth_tenants(id),integration_id BIGINT NOT NULL REFERENCES synth_integrations(id),event_ref TEXT NOT NULL,received_digest CHAR(64) NOT NULL,signature_valid BOOLEAN NOT NULL,received_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,integration_id,event_ref));
CREATE TABLE IF NOT EXISTS synth_provider_usage(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES synth_tenants(id),provider TEXT NOT NULL,operation TEXT NOT NULL,usage JSONB NOT NULL,usage_digest CHAR(64) NOT NULL,evidence_digest CHAR(64) NOT NULL,recorded_by BIGINT NOT NULL REFERENCES synth_users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,usage_digest));
CREATE TABLE IF NOT EXISTS synth_provider_failures(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES synth_tenants(id),job_id BIGINT REFERENCES synth_jobs(id),provider TEXT NOT NULL,operation TEXT NOT NULL,error_code TEXT NOT NULL,retryable BOOLEAN NOT NULL,sanitized_detail TEXT NOT NULL DEFAULT 'provider detail redacted',occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS synth_audit_events(id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES synth_tenants(id),job_id BIGINT REFERENCES synth_jobs(id),actor_id BIGINT REFERENCES synth_users(id),event_type TEXT NOT NULL,payload JSONB NOT NULL,evidence_digest CHAR(64),occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS synth_generation_ready_idx ON synth_generation_outbox(status,next_attempt_at);CREATE INDEX IF NOT EXISTS synth_notification_ready_idx ON synth_notification_outbox(status,next_attempt_at);CREATE INDEX IF NOT EXISTS synth_job_state_idx ON synth_jobs(tenant_id,state,updated_at);
CREATE OR REPLACE FUNCTION prevent_synth_evidence_mutation() RETURNS trigger AS $$BEGIN RAISE EXCEPTION 'synthetic data evidence is append-only';END;$$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION guard_synth_generation_request() RETURNS trigger AS $$BEGIN IF OLD.tenant_id<>NEW.tenant_id OR OLD.job_id<>NEW.job_id OR OLD.idempotency_key<>NEW.idempotency_key OR OLD.payload IS DISTINCT FROM NEW.payload OR OLD.payload_digest<>NEW.payload_digest OR OLD.created_at<>NEW.created_at THEN RAISE EXCEPTION 'generation request is immutable';END IF;RETURN NEW;END;$$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION guard_synth_notification_request() RETURNS trigger AS $$BEGIN IF OLD.tenant_id<>NEW.tenant_id OR OLD.integration_id<>NEW.integration_id OR OLD.event_type<>NEW.event_type OR OLD.idempotency_key<>NEW.idempotency_key OR OLD.message IS DISTINCT FROM NEW.message OR OLD.message_digest<>NEW.message_digest OR OLD.created_at<>NEW.created_at THEN RAISE EXCEPTION 'notification request is immutable';END IF;RETURN NEW;END;$$ LANGUAGE plpgsql;
DO $$DECLARE t TEXT;BEGIN FOREACH t IN ARRAY ARRAY['synth_specs','synth_privacy_reviews','synth_batches','synth_evaluations','synth_release_approvals','synth_releases','synth_webhook_receipts','synth_provider_usage','synth_audit_events'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS %I_append_only ON %I',t,t);EXECUTE format('CREATE TRIGGER %I_append_only BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION prevent_synth_evidence_mutation()',t,t);END LOOP;END$$;
DROP TRIGGER IF EXISTS synth_generation_request_guard ON synth_generation_outbox;CREATE TRIGGER synth_generation_request_guard BEFORE UPDATE ON synth_generation_outbox FOR EACH ROW EXECUTE FUNCTION guard_synth_generation_request();
DROP TRIGGER IF EXISTS synth_notification_request_guard ON synth_notification_outbox;CREATE TRIGGER synth_notification_request_guard BEFORE UPDATE ON synth_notification_outbox FOR EACH ROW EXECUTE FUNCTION guard_synth_notification_request();
COMMIT;
